import axios from 'axios';

// API Configuration
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Helper to get full API URL
export const getFullApiUrl = (path: string): string => {
  const normalizedPath = path.startsWith('/') ? path : `/${path}`;
  return `${API_BASE_URL}${normalizedPath}`;
};

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// API Types
export interface APIResponse<T = any> {
  success: boolean;
  message?: string;
  data?: T;
  error?: {
    code: string;
    message: string;
    details?: any;
  };
  timestamp: string;
}

export interface Job {
  job_id: string;
  job_type: string;
  parameters: any;
  status: 'pending' | 'running' | 'completed' | 'failed';
  result: any;
  error: string | null;
  created_at: string;
  completed_at: string | null;
}

export interface SystemStatus {
    data_files: { [key: string]: boolean };
    store_templates: string[];
    lob_status: { [key: string]: boolean };
    system_health: string;
    active_jobs: number;
    jobs: {
        total: number;
        running: number;
        completed: number;
        failed: number;
    };
}

export interface ValidParameters {
    lobs: string[];
    categories: string[];
    store_types: string[];
    strategies: string[];
    strategy_descriptions: { [key: string]: string };
}


// API Functions
export const apiService = {
  async generatePlanogram(storeName: string, selectedAccessories: string[]): Promise<{ job_id: string }> {
    const response = await api.post(`/api/stores/${storeName}/generate-planograms`, {
      selected_accessories: selectedAccessories,
    });
    return response.data;
  },

  async getJobDetails(jobId: string): Promise<Job> {
    const response = await api.get(`/api/jobs/${jobId}`);
    return response.data;
  },

  async getSystemStatus(): Promise<SystemStatus> {
    const response = await api.get('/api/system/info');
    return response.data;
  },

  async getValidParameters(): Promise<ValidParameters> {
    const response = await api.get('/api/validate/parameters');
    return response.data;
  },

  async getStoreTemplates(): Promise<any> {
    const response = await api.get('/api/stores/templates');
    return response.data;
  },

  async getStoreWalls(storeName: string): Promise<any> {
    const response = await api.get(`/api/stores/${storeName}/walls`);
    return response.data;
  },

  async getStoreRecommendations(storeName: string): Promise<any> {
    const response = await api.get(`/api/stores/${storeName}/recommendations`);
    return response.data;
  },

  async cancelJob(jobId: string): Promise<any> {
    const response = await api.post(`/api/jobs/${jobId}/cancel`);
    return response.data;
  }
};

export default api;
